mapper.select:
SELECT company_id AS companyId, #{statDate} AS statDate, #{statType} AS statType, SUM(CASE WHEN scan_type = 4 THEN 1 ELSE 0 END) AS fillCount, SUM(CASE WHEN scan_type = 5 THEN 1 ELSE 0 END) AS inspectionCount, SUM(CASE WHEN scan_type = 3 THEN 1 ELSE 0 END) AS inCount, SUM(CASE WHEN scan_type = 2 THEN 1 ELSE 0 END) AS outCount FROM scan_record WHERE 1 = 1
AND scan_time >= #{startTime}
AND scan_time < #{endTime}
GROUP BY company_id
